        <div className="page-heading"><div><span className="eyebrow">QUESTIONNAIRES / {String(questionnaires.length).padStart(2, "0")}</span><h1>–ê–Ω–∫–µ—Ç–∏</h1><p>–û–∫—Ä–µ–º—ñ customer —ñ guest –ø–æ—Ç–æ–∫–∏. –ü—É–±–ª—ñ—á–Ω–æ –¥–æ—Å—Ç—É–ø–Ω–∞ –ª–∏—à–µ –æ–ø—É–±–ª—ñ–∫–æ–≤–∞–Ω–∞ –∞–Ω–∫–µ—Ç–∞ –∑–∞ –ø—Ä–∏–≤–∞—Ç–Ω–∏–º –ø–æ—Å–∏–ª–∞–Ω–Ω—è–º.</p></div></div>
        {query.error ? <div className="status status--error">{query.error === "title" ? "–î–æ–¥–∞–π—Ç–µ –Ω–∞–∑–≤—É –∞–Ω–∫–µ—Ç–∏." : "–ê–Ω–∫–µ—Ç—É –Ω–µ —Å—Ç–≤–æ—Ä–µ–Ω–æ. –°–ø—Ä–æ–±—É–π—Ç–µ —â–µ —Ä–∞–∑."}</div> : null}
